    const char *getResultCodeTemplate(ResultCode code)
    {
        const int codeIndex = static_cast<int>(code);
        if (codeIndex < 0 || codeIndex >= RESULT_CODE_COUNT) return "";
        return RESULT_CODE_TEMPLATES[codeIndex];
    }

    const char *getResultCodeSourceName(ResultCode code)
    {
        const int codeIndex = static_cast<int>(code);
        if (codeIndex < 0 || codeIndex >= RESULT_CODE_COUNT) return "";
        return RESULT_CODE_SOURCE_NAMES[codeIndex];
    }

    const char *getCheckIdentifierSourceName(CheckIdentifier identifier)
    {
        const int identifierIndex = static_cast<int>(identifier);
        if (identifierIndex < 0 || identifierIndex >= CHECK_IDENTIFIER_COUNT) return "";
        return CHECK_IDENTIFIER_SOURCE_NAMES[identifierIndex];
    }
